use std::{fs,collections::BTreeMap,path::Path};
fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let s=fs::read_to_string(p.join("ANCHOR-CURVE-DIAGNOSTICS.tsv")).unwrap();let mut b:BTreeMap<(u64,u64,u64),(u64,u64,u64,u64,u64)>=BTreeMap::new();let mut calls=0u64;for l in s.lines(){let t:Vec<_>=l.split('\t').collect();assert_eq!(t[0],"ANCHOR");assert_eq!(t.len(),12);let v:Vec<u64>=t[1..].iter().map(|x|x.parse().unwrap()).collect();let(g,h,mode,rank)=(v[0],v[3],v[4],v[6]);let a=b.entry((g,h,mode)).or_default();a.0+=1;a.1+=u64::from(rank>0);a.2+=rank;a.3+=v[8];a.4+=u64::from(v[7]>0);calls+=1;}
let mut out=String::from("g\tH\tmode\tpolicies\tpositive_rank\trank_sum\tfull_closed_sum\tcomponent_available\n");for (&(g,h,mode),&(n,pos,r,c,comp)) in &b{out+=&format!("{g}\t{h}\t{mode}\t{n}\t{pos}\t{r}\t{c}\t{comp}\n");}fs::write(p.join("ANCHOR-SUMMARY.tsv"),&out).unwrap();print!("{out}");let syn=fs::read_to_string(p.join("ANCHOR-SYNTHETIC.tsv")).unwrap();let mut total=0u64;let mut zero=0u64;let mut closed=0u64;for l in syn.lines().skip(1){let v:Vec<u64>=l.split('\t').map(|x|x.parse().unwrap()).collect();total+=v[2];closed+=v[4];zero+=v[5];}let totals=format!("synthetic_cases={total}\nsynthetic_closed_cases={closed}\nsynthetic_zero_size_cases={zero}\ncurve_policies={calls}\n");print!("{totals}");fs::write(p.join("ANCHOR-TOTALS.txt"),totals).unwrap();
let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1050' height='540'><rect width='1050' height='540' fill='white'/><g font-family='Arial' fill='#183041'><text x='35' y='35' font-size='22'>Anchor intersection: eligible pencils with positive rank</text><text x='35' y='62' font-size='14'>Exact finite counts; canonical-prefix anchors. Rotated policies remain in ANCHOR-SUMMARY.tsv.</text>");
for (i,g) in [2u64,3,4].iter().enumerate(){let vals:Vec<_>=b.iter().filter(|(key,_)|key.0==*g&&key.2==0).collect();let n=vals.iter().map(|x|x.1.0).max().unwrap();let ox=65.+i as f64*330.;svg+=&format!("<text x='{ox}' y='104' font-size='18'>Genus {g} (eligible n={n})</text><path d='M {ox} 385 h 280' stroke='#64717a'/>");for (j,(key,val)) in vals.iter().enumerate(){let x=ox+15.+j as f64*53.;let height=val.1 as f64/24.*240.;svg+=&format!("<rect x='{x}' y='{:.2}' width='31' height='{height:.2}' fill='#287b83'/><text x='{x}' y='{:.2}' font-size='14'>{}</text><text x='{x}' y='408' font-size='13'>{}</text>",385.-height,375.-height,val.1,key.1);}svg+=&format!("<text x='{ox}' y='438' font-size='14'>H: number of anchor columns</text>");}
svg+="<text x='35' y='487' font-size='14'>Zero rank means no nonzero anchor-supported difference relation survives in that pencil.</text><text x='35' y='514' font-size='13'>hec_fibre_pencil_20261116 / anchor gate / fixed counts; no wall timing or population estimate.</text></g></svg>";fs::write(p.join("ANCHOR-COUNTS.svg"),svg).unwrap();}
